using Essco.Application;using Essco.Application.Returns;using Essco.Domain;using Essco.Domain.Returns;using Essco.SapBridge.Contracts;namespace Essco.Tests.Unit.Returns;public sealed class ReturnServiceTests{[Fact]public async Task Dispatch_requires_lines(){var r=await new ReturnService(new Repo(false),new Queue()).DispatchAsync(1,"E","u",default);Assert.False(r.Succeeded);}[Fact]public async Task Dispatch_is_idempotent_by_number(){var q=new Queue();var r=await new ReturnService(new Repo(true),q).DispatchAsync(1,"E","u",default);Assert.True(r.Succeeded);Assert.Equal("return:1:credit-note",q.Request!.IdempotencyKey);}private sealed class Repo(bool lines):IReturnRepository{public ValueTask<ReturnRequest?>GetAsync(int n,CancellationToken t)=>ValueTask.FromResult<ReturnRequest?>(new(n,new(2026,1,1),"1","A","C1","C",false,10,"F","M",false,null,"","","",lines?[new(1,"I","Item",10,1,0,0,13,10,"M","","01")]:[]));public ValueTask<IReadOnlyCollection<ReturnRequest>>ListAsync(ReturnFilter f,CancellationToken t)=>ValueTask.FromResult<IReadOnlyCollection<ReturnRequest>>([]);public ValueTask<bool>MarkProcessedAsync(int n,int e,CancellationToken t)=>ValueTask.FromResult(true);}private sealed class Queue:ISapJobQueue{public CreateSapJobRequest?Request{get;private set;}public ValueTask<SapJob>EnqueueAsync(CreateSapJobRequest r,CancellationToken t){Request=r;return ValueTask.FromResult(new SapJob{OperationType=r.OperationType,Company=r.Company,RequestedBy=r.RequestedBy,Payload=r.Payload});}public ValueTask<SapJob?>ClaimNextAsync(CancellationToken t)=>ValueTask.FromResult<SapJob?>(null);public ValueTask CompleteAsync(Guid i,string e,CancellationToken t)=>ValueTask.CompletedTask;public ValueTask FailAsync(Guid i,string e,bool r,CancellationToken t)=>ValueTask.CompletedTask;public ValueTask<IReadOnlyCollection<SapJob>>GetSnapshotAsync(CancellationToken t)=>ValueTask.FromResult<IReadOnlyCollection<SapJob>>([]);}}
